{
  "id": "ch1-logic-linear-semilinear",
  "title": "第1章 逻辑结构：从抽象模型看线性与半线性",
  "subtitle": "数据关系的抽象分类：集合、线性、树形与图形",
  "language": "zh-CN",
  "audience": "计算机科学本科一年级学生",
  "theme": "slate",
  "tutor": {
    "suggestions": [
      "为什么栈和队列仍属于线性结构，而不是独立的逻辑结构？",
      "树被称为“半线性”结构，这个“半”字具体体现在哪里？",
      "同一逻辑结构为什么可以有多种存储实现？请举例说明。",
      "ADT 的三要素中，“数据关系”和“基本操作”分别起什么作用？"
    ],
    "kb": [
      {
        "pattern": "逻辑结构|数据关系",
        "answer": "数据元素之间的抽象关系，如线性、树形、图形，独立于具体的存储方式。"
      },
      {
        "pattern": "存储结构|物理结构",
        "answer": "数据在内存中的实际表示方式，如顺序存储、链式存储、索引存储、散列存储。"
      },
      {
        "pattern": "线性表|前驱-后继",
        "answer": "元素之间一对一的邻接关系，除首尾外每个元素有唯一前驱和唯一后继。"
      },
      {
        "pattern": "栈|LIFO",
        "answer": "操作受限的线性表，后进先出，只允许在栈顶一端进行插入和删除。"
      },
      {
        "pattern": "队列|FIFO",
        "answer": "操作受限的线性表，先进先出，在一端入队、另一端出队。"
      },
      {
        "pattern": "树|半线性",
        "answer": "节点之间一对多的层次关系，但任意两节点之间有且仅有一条简单路径。"
      }
    ]
  },
  "scenes": [
    {
      "id": "s1-1-abstraction",
      "kind": "content",
      "eyebrow": "1.1 抽象与实现",
      "headline": "数据结构：从问题到抽象模型",
      "lead": "逻辑结构描述的是数据元素之间的数学关系，与它们在内存中的存储方式无关。",
      "notes": "先让学生意识到数据结构不是代码实现，而是对问题的抽象。四大分类的核心差异是“元素之间允许什么样的关系”：集合没有关系，线性是一对一，树是一对多，图是多对多。强调逻辑结构与存储结构解耦，例如同样的线性表既可以用数组实现，也可以用链表实现。",
      "blocks": [
        {
          "id": "b1-1-statement",
          "type": "statement",
          "intent": "给出核心定义：数据结构 = 数据对象 + 数据关系 + 基本操作；其中数据关系即逻辑结构，是算法设计的出发点。",
          "size": "m"
        },
        {
          "id": "b1-1-list",
          "type": "list",
          "intent": "列出四大逻辑结构及其典型实例，帮助学生建立分类框架。",
          "size": "m"
        },
        {
          "id": "b1-1-callout",
          "type": "callout",
          "intent": "强调逻辑结构与存储结构是两个独立维度，同一逻辑结构可对应多种实现。",
          "size": "s"
        }
      ]
    },
    {
      "id": "s1-2-linear",
      "kind": "content",
      "eyebrow": "1.2 线性结构",
      "headline": "一对一的前驱-后继关系",
      "lead": "线性表中除首尾外，每个元素有且仅有一个直接前驱和一个直接后继。",
      "notes": "用火车车厢或播放列表作为直觉锚点：每一节车厢只连接前一节和后一节。线性关系的数学表达是二元组 $<a_i,a_{i+1}>$。重点纠偏：栈和队列不是新的逻辑结构，它们在线性表的基础上限制了操作位置，因此逻辑关系仍然是一对一。",
      "blocks": [
        {
          "id": "b1-2-statement",
          "type": "statement",
          "intent": "用数学语言刻画线性关系：元素序列 $a_1, a_2, \\dots, a_n$ 与二元组关系。",
          "size": "m"
        },
        {
          "id": "b1-2-flow",
          "type": "flow",
          "intent": "用 flow 展示线性链：车头 → 车厢1 → 车厢2 → 车厢3，体现一对一邻接。",
          "size": "m"
        },
        {
          "id": "b1-2-callout",
          "type": "callout",
          "intent": "纠正常见误区：栈和队列是操作受限的线性表，不是新的逻辑结构。",
          "size": "s"
        },
        {
          "id": "b1-2-list",
          "type": "list",
          "intent": "补充生活实例：播放列表、火车车厢、CPU 任务队列。",
          "size": "s"
        }
      ]
    },
    {
      "id": "s1-3-tree",
      "kind": "content",
      "eyebrow": "1.3 半线性结构",
      "headline": "树：一对多的层次关系",
      "lead": "树放宽了线性的“唯一后继”限制，但保留了“任意两节点之间有且仅有一条路径”的半线性特征。",
      "notes": "树是本章最难的概念，“半线性”需要具象化：它比线性多分支，但又不像图那样任意连接。文件系统是最贴切的例子——/home 下可以有多个子目录，但从根目录到任意文件只有一条路径。用 pyramid 图把层次和唯一路径同时可视化。",
      "blocks": [
        {
          "id": "b1-3-statement",
          "type": "statement",
          "intent": "定义树的核心性质：根可有多个子节点，非根节点有唯一父节点，根到任一节点路径唯一。",
          "size": "m"
        },
        {
          "id": "b1-3-diagram",
          "type": "diagram",
          "intent": "用 pyramid 展示文件系统层次：/ → home / usr / etc → 子目录与文件，体现一对多和唯一路径。",
          "size": "l"
        },
        {
          "id": "b1-3-list",
          "type": "list",
          "intent": "总结树的三大关键性质：层次性、唯一路径、无环。",
          "size": "s"
        }
      ]
    },
    {
      "id": "s1-4-adt-paradigm",
      "kind": "content",
      "eyebrow": "1.4 ADT 与算法范式",
      "headline": "逻辑结构决定操作接口",
      "lead": "抽象数据类型用数据对象、数据关系、基本操作三要素封装结构，而逻辑结构直接决定常用算法范式。",
      "notes": "ADT 三要素要把“关系”和“操作”分开：关系是静态结构，操作是动态接口。不同逻辑结构天然适合不同算法范式：线性表支持随机/顺序访问，栈产生 LIFO，队列产生 FIFO，树产生层次遍历。提醒学生先选逻辑结构，再定实现。",
      "blocks": [
        {
          "id": "b1-4-list",
          "type": "list",
          "intent": "拆解 ADT 三要素：数据对象、数据关系、基本操作。",
          "size": "m"
        },
        {
          "id": "b1-4-table",
          "type": "table",
          "intent": "用表格映射逻辑结构到典型算法范式：集合-成员判定、线性表-随机/顺序访问、栈-LIFO、队列-FIFO、树-层次遍历、图-搜索遍历。",
          "size": "m"
        },
        {
          "id": "b1-4-callout",
          "type": "callout",
          "intent": "给出设计顺序：先确定元素关系，再确定操作集合，最后选择存储实现。",
          "size": "s"
        }
      ]
    },
    {
      "id": "s1-5-quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "notes": "通过四道选项检查学生是否区分逻辑结构与操作限制、树的路径唯一性、ADT 三要素。正确选项 C 直接对应本章核心观点：逻辑结构独立于存储结构。讲解时顺带排除 A（栈/队列是受限线性表）、B（树路径唯一）、D（ADT 还包含关系和操作）。",
      "blocks": [
        {
          "id": "b1-5-quiz",
          "type": "quiz",
          "intent": "单选题：下列关于数据结构的叙述中，哪一项是正确的？A. 栈和队列是不同于线性表的逻辑结构；B. 树的任意两节点之间可能存在多条路径；C. 逻辑结构与存储结构无关；D. ADT 只包含数据对象。正确答案：C。",
          "size": "m"
        }
      ]
    }
  ]
}
